def apply_transformation(grid):
    """Apply pattern: objects fall down by bar_row distance, bar stays in place."""
    # Find bar row and value
    for r, row in enumerate(grid):
        if all(c == row[0] and c != 0 for c in row):
            bar_row = r
            bar_val = row[0]
            break

    # Build output with bar in place
    out = [['0' for c in len(grid[0])] for r in range(len(grid))]
    for r, row in enumerate(grid):
        for c in range(len(grid[0])):
            if row[c] == bar_val:
                out[bar_row][c] = str(row[c])

    # Shift all non-bar cells down by bar_row
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val != 0 and val != bar_val:
                # Move to row r + bar_row
                new_r = r + bar_row
                if new_r < len(out):
                    out[new_r][c] = str(val)

    return out

