        if all(c == row[0] and c != 0 for c in row):
            bar_row = r
            bar_val = row[0]
            break

    # Build output with bar in place
    out = [['0' for _ in range(cols)] for _ in range(rows)]
    for r, row in enumerate(grid):
        for c in range(cols):
            if row[c] == bar_val:
                out[bar_row][c] = str(row[c])

